  if (recvwndo > UINT16_MAX)
    {
      recvwndo = UINT16_MAX;
    }

#ifdef CONFIG_NET_TCP_WINDOW_SCALE
  recvwndo <<= conn->rcv_scale;
#endif

  return recvwndo;
}

