Return the number of mismatching words/bytes; set *first_bad to the absolute offset of the first mismatch (UINT64_MAX if none). Implementation:
```c
static uint64_t ethloop_pattern_check(const uint8_t *buf, uint64_t off, size_t len, uint64_t *first_bad)
{
  size_t i = 0;
  uint64_t bad = 0;
  *first_bad = UINT64_MAX;

  while (i < len)
    {
      if ((off & 3) == 0 && len - i >= 4)
        {
          uint32_t word;
          memcpy(&word, &buf[i], 4);
          if (word != (uint32_t)(off >> 2))
            {
              if (*first_bad == UINT64_MAX) *first_bad = off;
              bad++;
            }
          i += 4; off += 4;
        }
      else
        {
          if (buf[i] != ethloop_pattern_byte(off))
            {
              if (*first_bad == UINT64_MAX) *first_bad = off;
              bad++;
            }
          i++; off++;
        }
    }
  return bad;
}
