Send_all:
```c
static ssize_t ethloop_send_all(FAR struct ethloop_conn_s *conn,
                                FAR const uint8_t *buf, size_t len)
{
  size_t sent = 0;

  while (sent < len)
    {
      ssize_t n = send(conn->fd, buf + sent, len - sent, 0);
      if (n > 0) { sent += n; continue; }
      if (n == 0) { return -EPIPE; }
      if (errno == EINTR) continue;
      if (errno == EAGAIN || errno == EWOULDBLOCK)
        {
          if (ethloop_conn_done(conn)) return -ECANCELED;
          continue;
        }
      return -errno;
    }
  return (ssize_t)sent;
}
```
