 * License for the specific language governing permissions and limitations
 * under the License.
 *
 ****************************************************************************/

/****************************************************************************
 * A bulk TCP stream between the board's two wired ports, with the ports
 * cabled to each other.
 *
 * The program is both ends at once: a server task listens on the address of
 * if1, and the main task connects to it from if0.  Every byte therefore has
 * to leave one port, cross the cable, and be received by the other port; the
 * reply direction crosses back.  The application measures how fast that can
 * be done and whether the bytes survive the trip.
 *
 * Why the two ports have to share a subnet
 * ----------------------------------------
 * This is what makes a single-board loopback work, and it is not obvious.
 *
 * A TCP segment is transmitted on the interface that the destination
 * address routes to.  Its Ethernet destination MAC is resolved by ARP on
 * that same interface, and arp_out() will only ARP for an address that is on
 * that interface's own subnet.  It otherwise wants a router, and across a
 * cable there is none.
 *
 * Put if0 and if1 on different subnets and both rules point the wrong way: a
 * segment for if1's address is sent out if1, arrives on if0 (the cable
 * connects a transmitter to the other port's receiver), and if0 drops it --
 * the address is not if0's.  Nothing useful crosses the cable and the
 * connection times out with no error anywhere.
 *
 * Put both ports on one subnet instead, and bind the connecting socket to
 * if0 with SO_BINDTODEVICE.  bind() is where NuttX picks the connection's
 * device, and it only looks at SO_BINDTODEVICE when the bound address is
 * INADDR_ANY, so the option has to be set first.  After that:
 *
 *   - the client's segments are transmitted on if0, with the source address
 *     taken from if0 (tcp_send() always writes dev->d_ipaddr into the IP
 *     header, so binding the device also fixes the source address);
 *   - the destination is on if0's subnet, so the ARP request for it goes out
 *     if0 and is answered by if1 on the other side of the cable;
 *   - the server's accepted connection keeps the device the SYN arrived on
 *     (tcp_alloc_accept() sets conn->dev = dev), so its replies leave if1;
 *   - connections are polled only on the device they are bound to, so the
 *     client's stream and the server's stream never meet in one driver.
 *
 * Each direction carries a pattern that the receiver checks: a 32-bit word
 * whose value is its own index in the stream.  A word that does not match is
 * a corrupted byte on the wire or in the driver, not merely a lost one, so
 * this tells "TCP retransmitted" apart from "the DMA wrote garbage".
 *
 * The test is meant to survive failure: a connection that breaks before the
 * deadline is reported and reopened, and one on which no byte has moved for
 * five seconds is abandoned so that the run can continue.  Pulling the cable
 * in the middle of a run is therefore a useful thing to do, and the summary
 * says how many connections were lost and recovered.
 *
 * Throughput caveat: this is a uniprocessor NuttX build.  Both endpoints,
 * the TCP stack, the driver's receive path and the pattern check share one
 * core, and a single connection can hold only its socket's send buffer in
 * flight.  A rate well below the wire rate can be the stack rather than the
 * PHY.  The banner and the summary print the buffer sizes so the two can be
 * told apart, and -w raises the send buffer to the extent the IOB pool
 * allows.
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/socket.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <net/if.h>
#include <poll.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "netutils/netlib.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* The two ends of the test.  The addresses are deliberately in a range a
 * board is unlikely to meet on a bench network, and the mask is fixed: the
 * whole scheme above depends on both addresses being on one subnet.
 */

#define ETHLOOP_DEFAULT_IF0      "eth0"
#define ETHLOOP_DEFAULT_IF1      "eth1"
#define ETHLOOP_DEFAULT_ADDR0    "192.168.77.1"
#define ETHLOOP_DEFAULT_ADDR1    "192.168.77.2"
#define ETHLOOP_DEFAULT_MASK     "255.255.255.0"
#define ETHLOOP_DEFAULT_PORT     5201
#define ETHLOOP_DEFAULT_SECONDS  30
#define ETHLOOP_DEFAULT_CHUNK    16384
#define ETHLOOP_DEFAULT_SNDBUF   (32 * 1024)

/* One chunk is one send() and one recv().  The maximum is also the size of
 * each of the four static buffers below; keeping the traffic out of the heap
 * means the test cannot fail for want of a malloc() in the middle of a run.
 */

#define ETHLOOP_CHUNK_MAX        32768

/* The deadline is checked between chunks, and a blocking send()/recv() is
 * bounded by these timeouts so that no loop can sit in the socket beyond a
 * deadline or a dead link.
 */

#define ETHLOOP_IO_TIMEOUT_MS    300
#define ETHLOOP_CONNECT_MS       2000
#define ETHLOOP_PROGRESS_MS      5000
#define ETHLOOP_LINK_WAIT_MS     15000

#define ETHLOOP_NS_PER_MS        1000000LL
#define ETHLOOP_NS_PER_S         1000000000LL

/****************************************************************************
 * Private Types
 ****************************************************************************/

enum ethloop_mode_e
{
  ETHLOOP_MODE_TX = 0,          /* if0 to if1 only                      */
  ETHLOOP_MODE_RX,              /* if1 to if0 only                      */
  ETHLOOP_MODE_BOTH,            /* both directions at the same time     */
};

enum ethloop_dir_e
{
  ETHLOOP_DIR_FWD = 0,          /* if0 -> if1 (the client sends)        */
  ETHLOOP_DIR_REV,              /* if1 -> if0 (the server sends)        */
  ETHLOOP_NDIR
};

/* One direction's counters.  The receiver's rx_bytes is the number that
 * crossed the cable and was read by the application; the sender's tx_bytes
 * is what was handed to the socket.  They differ by whatever was still in
 * flight when the connection was closed.
 */

struct ethloop_dir_s
{
  volatile uint64_t tx_bytes;
  volatile uint64_t rx_bytes;
  volatile uint64_t bad_words;

  /* Per-second samples, in tenths of a Mbit/s.  Only the reporting thread
   * touches these.
   */

  uint64_t samples;
  uint64_t min_mbit_x10;
  uint64_t max_mbit_x10;
  uint64_t prev_rx;
};

/* One end of the TCP connection, as seen by the threads working on it.  The
 * primary loop of each side checks 'stop' and 'failed'; a worker that hits a
 * fatal socket error sets 'failed' so that the other direction winds up too.
 */

struct ethloop_conn_s
{
  int fd;
  volatile bool stop;
  volatile bool failed;
  volatile bool peer_gone;
  int err;
  const char *where;
};

/* What a sender or receiver thread needs to know.  One instance per
 * direction per side; the buffers are static and never shared.
 */

struct ethloop_io_s
{
  struct ethloop_conn_s *conn;
  int dir;
  uint8_t *buf;
  bool reporter;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const char *g_ifname[2];
static struct in_addr g_addr[2];
static struct in_addr g_netmask;
static uint16_t g_port;
static int g_seconds;
static int g_mode;
static size_t g_chunk;
static int g_sndbuf;
static bool g_setup;
static bool g_verify;

static volatile bool g_stop;
static int64_t g_start_ns;
static int64_t g_deadline_ns;
static int64_t g_last_report_ns;
static int64_t g_last_progress_ns;

static struct ethloop_dir_s g_dir[ETHLOOP_NDIR];

static int g_connections;
static int g_drops;
static int g_connect_errors;
static bool g_sndbuf_shown;

/* The client's buffers are used by the sending and receiving direction on
 * if0; the server's by the same on if1.  Each side needs one buffer per
 * direction because in 'both' mode its sender and receiver run at once.
 */

static uint8_t g_client_tx[ETHLOOP_CHUNK_MAX];
static uint8_t g_client_rx[ETHLOOP_CHUNK_MAX];
static uint8_t g_server_tx[ETHLOOP_CHUNK_MAX];
static uint8_t g_server_rx[ETHLOOP_CHUNK_MAX];

static struct ethloop_conn_s g_client_conn;
static struct ethloop_conn_s g_server_conn;

static struct ethloop_io_s g_client_fwd =
{
  .conn     = &g_client_conn,
  .dir      = ETHLOOP_DIR_FWD,
  .buf      = g_client_tx,
  .reporter = false,
};

static struct ethloop_io_s g_client_rev =
{
  .conn     = &g_client_conn,
  .dir      = ETHLOOP_DIR_REV,
  .buf      = g_client_rx,
  .reporter = false,
};

static struct ethloop_io_s g_server_fwd =
{
  .conn     = &g_server_conn,
  .dir      = ETHLOOP_DIR_FWD,
  .buf      = g_server_rx,
  .reporter = false,
};

static struct ethloop_io_s g_server_rev =
{
  .conn     = &g_server_conn,
  .dir      = ETHLOOP_DIR_REV,
  .buf      = g_server_tx,
  .reporter = false,
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: ethloop_now_ns
 ****************************************************************************/

static int64_t ethloop_now_ns(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (int64_t)ts.tv_sec * ETHLOOP_NS_PER_S + ts.tv_nsec;
}

/****************************************************************************
 * Name: ethloop_span_ms
 *
 * Description:
 *   Milliseconds from 'since' to 'now', never negative.
 *
 ****************************************************************************/

static uint64_t ethloop_span_ms(int64_t since, int64_t now)
{
  int64_t diff = now - since;

  return diff > 0 ? (uint64_t)(diff / ETHLOOP_NS_PER_MS) : 0;
}

/****************************************************************************
 * Name: ethloop_signal
 ****************************************************************************/

static void ethloop_signal(int signo)
{
  (void)signo;
  g_stop = true;
}

/****************************************************************************
 * Name: ethloop_stopping
 *
 * Description:
 *   The test-level stop condition: a signal, or the deadline.  The first
 *   caller to reach the deadline sets g_stop, so every other thread sees it
 *   on its next check.
 *
 ****************************************************************************/

static bool ethloop_stopping(void)
{
  if (!g_stop && g_deadline_ns != 0 && ethloop_now_ns() >= g_deadline_ns)
    {
      g_stop = true;
    }

  return g_stop;
}

/****************************************************************************
 * Name: ethloop_conn_done
 *
 * Description:
 *   The per-connection stop condition.  A worker that sees this must leave
 *   its loop; the side's owner then closes the socket.
 *
 ****************************************************************************/

static bool ethloop_conn_done(const struct ethloop_conn_s *conn)
{
  return ethloop_stopping() || conn->stop || conn->failed || conn->peer_gone;
}

/****************************************************************************
 * Name: ethloop_progress
 *
 * Description:
 *   Note that bytes moved.  The reporter uses the absence of this for five
 *   seconds as "the connection is wedged" -- TCP itself would keep
 *   retransmitting for minutes before giving up, which is far too long for
 *   a test that is supposed to recover.
 *
 ****************************************************************************/

static void ethloop_progress(void)
{
  g_last_progress_ns = ethloop_now_ns();
}

/****************************************************************************
 * Name: ethloop_pattern_byte
 *
 * Description:
 *   Byte 'off' of the pattern: word (off / 4) = (off / 4), little-endian
 *   because both ends are this same CPU.  Any other byte order would still
 *   verify; it is the identity of the word that matters.
 *
 ****************************************************************************/

static inline uint8_t ethloop_pattern_byte(uint64_t off)
{
  uint32_t word = (uint32_t)(off >> 2);

  return (uint8_t)(word >> (8 * (off & 3)));
}

/****************************************************************************
 * Name: ethloop_pattern_fill
 *
 * Description:
 *   Fill 'len' bytes with the pattern at stream offset 'off'.  'off' need
 *   not be word-aligned: send() may accept a partial chunk, and the next
 *   fill then starts in the middle of a word.  Both ends use these two
 *   functions, so any split point agrees.
 *
 ****************************************************************************/

static void ethloop_pattern_fill(uint8_t *buf, uint64_t off, size_t len)
{
  size_t i = 0;

  while (i < len && (off & 3) != 0)
    {
      buf[i++] = ethloop_pattern_byte(off++);
    }

  while (i + sizeof(uint32_t) <= len)
    {
      uint32_t word = (uint32_t)(off >> 2);

      memcpy(&buf[i], &word, sizeof(word));
      i += sizeof(word);
      off += sizeof(word);
    }

  while (i < len)
    {
      buf[i++] = ethloop_pattern_byte(off++);
    }
}

/****************************************************************************
 * Name: ethloop_pattern_check
 *
 * Description:
 *   Compare 'len' received bytes against the pattern at stream offset
 *   'off'.  Returns the number of mismatching words (or bytes, at the ends
 *   of a partial chunk) and, in *first_bad, the absolute offset of the first
 *   one, or UINT64_MAX if the chunk is clean.
 *
 ****************************************************************************/

static uint64_t ethloop_pattern_check(const uint8_t *buf, uint64_t off,
                                      size_t len, uint64_t *first_bad)
{
  size_t i = 0;
  uint64_t bad = 0;

  *first_bad = UINT64_MAX;

  while (i < len)
    {
      if ((off & 3) == 0 && len - i >= sizeof(uint32_t))
        {
          uint32_t word;

          memcpy(&word, &buf[i], sizeof(word));
          if (word != (uint32_t)(off >> 2))
            {
              if (*first_bad == UINT64_MAX)
                {
                  *first_bad = off;
                }

              bad++;
            }

          i += sizeof(word);
          off += sizeof(word);
        }
      else
        {
          if (buf[i] != ethloop_pattern_byte(off))
            {
              if (*first_bad == UINT64_MAX)
                {
                  *first_bad = off;
                }

              bad++;
            }

          i++;
          off++;
        }
    }

  return bad;
}

/****************************************************************************
 * Name: ethloop_format_x10
 *
 * Description:
 *   Format tenths of a unit as "123.4".  Fixed point on purpose:
 *   CONFIG_LIBC_FLOATINGPOINT is not needed for a test program, and printf's
 *   %f would drag it in.
 *
 ****************************************************************************/

static void ethloop_format_x10(char *buf, size_t size, uint64_t value)
{
  snprintf(buf, size, "%llu.%llu", (unsigned long long)(value / 10),
           (unsigned long long)(value % 10));
}

/****************************************************************************
 * Name: ethloop_mbit_x10 / ethloop_mbyte_x10
 *
 * Description:
 *   'bytes' over 'ns' as tenths of a Mbit/s, and as tenths of a MB/s
 *   (decimal, the units a link rate is quoted in).
 *
 ****************************************************************************/

static uint64_t ethloop_mbit_x10(uint64_t bytes, uint64_t ns)
{
  return ns != 0 ? bytes * 80000 / ns : 0;
}

static uint64_t ethloop_mbyte_x10(uint64_t bytes, uint64_t ns)
{
  return ns != 0 ? bytes * 10000 / ns : 0;
}

/****************************************************************************
 * Name: ethloop_dir_active
 ****************************************************************************/

static bool ethloop_dir_active(int dir)
{
  if (g_mode == ETHLOOP_MODE_BOTH)
    {
      return true;
    }

  return g_mode == (dir == ETHLOOP_DIR_FWD ? ETHLOOP_MODE_TX
                                           : ETHLOOP_MODE_RX);
}

/****************************************************************************
 * Name: ethloop_dir_name
 *
 * Description:
 *   "if0->if1" with the real names.  Two static buffers so that one call
 *   does not overwrite the result of another in the same printf.
 *
 ****************************************************************************/

static const char *ethloop_dir_name(int dir)
{
  static char name[2][2 * IFNAMSIZ + 4];

  snprintf(name[dir], sizeof(name[dir]), "%s->%s",
           dir == ETHLOOP_DIR_FWD ? g_ifname[0] : g_ifname[1],
           dir == ETHLOOP_DIR_FWD ? g_ifname[1] : g_ifname[0]);
  return name[dir];
}

/****************************************************************************
 * Name: ethloop_report
 *
 * Description:
 *   Print one line per second of test time, from the client's primary loop.
 *   This is also where the no-progress watchdog lives, because it is the
 *   only place that already looks at the clock once a second.
 *
 ****************************************************************************/

static void ethloop_report(struct ethloop_conn_s *conn)
{
  char mbyte[24];
  char mbit[24];
  int64_t now = ethloop_now_ns();
  int64_t span = now - g_last_report_ns;
  uint64_t elapsed;
  int dir;

  if (span < ETHLOOP_NS_PER_S)
    {
      return;
    }

  elapsed = ethloop_span_ms(g_start_ns, now);
  printf("%7llu.%llus", (unsigned long long)(elapsed / 1000),
         (unsigned long long)(elapsed % 1000 / 100));

  for (dir = 0; dir < ETHLOOP_NDIR; dir++)
    {
      struct ethloop_dir_s *d = &g_dir[dir];
      uint64_t rx = d->rx_bytes;
      uint64_t delta = rx - d->prev_rx;
      uint64_t mbit_x10 = ethloop_mbit_x10(delta, (uint64_t)span);
      uint64_t mbyte_x10 = ethloop_mbyte_x10(delta, (uint64_t)span);

      d->prev_rx = rx;

      if (!ethloop_dir_active(dir))
        {
          continue;
        }

      ethloop_format_x10(mbyte, sizeof(mbyte), mbyte_x10);
      ethloop_format_x10(mbit, sizeof(mbit), mbit_x10);
      printf("  %s %6s MB/s (%7s Mbit/s)", ethloop_dir_name(dir), mbyte,
             mbit);

      d->samples++;
      if (mbit_x10 < d->min_mbit_x10)
        {
          d->min_mbit_x10 = mbit_x10;
        }

      if (mbit_x10 > d->max_mbit_x10)
        {
          d->max_mbit_x10 = mbit_x10;
        }
    }

  printf("\n");

  /* Five seconds without a byte in either direction is a wedged connection,
   * not a slow one.  Failing it here lets the client drop it and reconnect.
   */

  if (!g_stop && conn != NULL && !conn->failed && !conn->stop &&
      g_last_progress_ns != 0 &&
      now - g_last_progress_ns > ETHLOOP_PROGRESS_MS * ETHLOOP_NS_PER_MS)
    {
      conn->failed = true;
      conn->err = ETIMEDOUT;
      conn->where = "progress";
      printf("ethloop: no byte moved for %d s, abandoning the connection\n",
             ETHLOOP_PROGRESS_MS / 1000);
    }

  g_last_report_ns = now;
}

/****************************************************************************
 * Name: ethloop_send_all
 *
 * Description:
 *   Queue all of 'buf' on 'conn'.  A blocking socket with TCP write buffers
 *   can still return a partial count or EAGAIN (SO_SNDTIMEO), so the loop is
 *   needed.  EAGAIN with the test still running means the peer's window is
 *   shut for the moment and is retried; with the test stopping it means the
 *   caller can leave.
 *
 ****************************************************************************/

static ssize_t ethloop_send_all(struct ethloop_conn_s *conn,
                                const uint8_t *buf, size_t len)
{
  size_t sent = 0;

  while (sent < len)
    {
      ssize_t n = send(conn->fd, buf + sent, len - sent, 0);

      if (n > 0)
        {
          sent += n;
          continue;
        }

      if (n == 0)
        {
          return -EPIPE;
        }

      if (errno == EINTR)
        {
          continue;
        }

      if (errno == EAGAIN || errno == EWOULDBLOCK)
        {
          if (ethloop_conn_done(conn))
            {
              return -ECANCELED;
            }

          continue;
        }

      return -errno;
    }

  return (ssize_t)sent;
}

/****************************************************************************
 * Name: ethloop_sender
 ****************************************************************************/

static void *ethloop_sender(void *arg)
{
  struct ethloop_io_s *io = arg;
  struct ethloop_conn_s *conn = io->conn;
  uint64_t off = 0;

  while (!ethloop_conn_done(conn))
    {
      ssize_t n;

      ethloop_pattern_fill(io->buf, off, g_chunk);
      n = ethloop_send_all(conn, io->buf, g_chunk);
      if (n == -ECANCELED)
        {
          break;
        }

      if (n < 0)
        {
          conn->failed = true;
          conn->err = (int)-n;
          conn->where = "send";
          break;
        }

      off += n;
      g_dir[io->dir].tx_bytes += n;
      ethloop_progress();

      if (io->reporter)
        {
          ethloop_report(conn);
        }
    }

  return NULL;
}

/****************************************************************************
 * Name: ethloop_receiver
 ****************************************************************************/

static void *ethloop_receiver(void *arg)
{
  struct ethloop_io_s *io = arg;
  struct ethloop_conn_s *conn = io->conn;
  uint64_t off = 0;
  bool reported = false;

  while (!ethloop_conn_done(conn))
    {
      ssize_t n = recv(conn->fd, io->buf, g_chunk, 0);

      if (n > 0)
        {
          g_dir[io->dir].rx_bytes += n;

          if (g_verify)
            {
              uint64_t first_bad;
              uint64_t bad = ethloop_pattern_check(io->buf, off, n,
                                                   &first_bad);

              if (bad != 0)
                {
                  g_dir[io->dir].bad_words += bad;

                  if (!reported)
                    {
                      reported = true;
                      printf("ethloop: %s corrupt data at stream offset %llu\n",
                             ethloop_dir_name(io->dir),
                             (unsigned long long)first_bad);
                    }
                }
            }

          off += n;
          ethloop_progress();

          if (io->reporter)
            {
              ethloop_report(conn);
            }

          continue;
        }

      if (n == 0)
        {
          conn->peer_gone = true;
          break;
        }

      if (errno == EINTR)
        {
          continue;
        }

      if (errno == EAGAIN || errno == EWOULDBLOCK)
        {
          if (io->reporter)
            {
              ethloop_report(conn);
            }

          continue;
        }

      conn->failed = true;
      conn->err = errno;
      conn->where = "recv";
      break;
    }

  return NULL;
}

/****************************************************************************
 * Name: ethloop_conn_report
 *
 * Description:
 *   Report a connection that failed.  An orderly close is part of the test
 *   ending and is not interesting on its own.
 *
 ****************************************************************************/

static void ethloop_conn_report(const char *side,
                                const struct ethloop_conn_s *conn,
                                uint64_t duration_ms)
{
  if (conn->failed)
    {
      printf("ethloop: %s: connection failed after %llu.%llus (%s: %s)\n",
             side, (unsigned long long)(duration_ms / 1000),
             (unsigned long long)(duration_ms % 1000 / 100),
             conn->where != NULL ? conn->where : "socket",
             strerror(conn->err));
    }
}

/****************************************************************************
 * Name: ethloop_socket_options
 ****************************************************************************/

static void ethloop_socket_options(int fd)
{
  struct timeval tv;

  if (g_sndbuf > 0)
    {
      if (setsockopt(fd, SOL_SOCKET, SO_SNDBUF, &g_sndbuf,
                     sizeof(g_sndbuf)) < 0)
        {
          fprintf(stderr, "ethloop: SO_SNDBUF %d failed: %d\n", g_sndbuf,
                  errno);
        }
    }

  tv.tv_sec = 0;
  tv.tv_usec = ETHLOOP_IO_TIMEOUT_MS * 1000;
  setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
  setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
}

/****************************************************************************
 * Name: ethloop_client_connect
 *
 * Description:
 *   Open the connection from if0 to if1.  SO_BINDTODEVICE is set before
 *   bind() because that is the call that fixes the connection's device; see
 *   the comment at the top of the file.  The connect itself is non-blocking
 *   so that a missing listener or an unresolved ARP entry costs two
 *   seconds, not TCP's own SYN retry budget.
 *
 ****************************************************************************/

static int ethloop_client_connect(void)
{
  struct sockaddr_in local;
  struct sockaddr_in remote;
  struct pollfd pfd;
  socklen_t optlen;
  int flags;
  int sockerr = 0;
  int fd;
  int saved;

  fd = socket(AF_INET, SOCK_STREAM, 0);
  if (fd < 0)
    {
      return -1;
    }

  if (setsockopt(fd, SOL_SOCKET, SO_BINDTODEVICE, g_ifname[0],
                 strlen(g_ifname[0]) + 1) < 0)
    {
      fprintf(stderr, "ethloop: SO_BINDTODEVICE %s failed: %d\n",
              g_ifname[0], errno);
      goto errout;
    }

  memset(&local, 0, sizeof(local));
  local.sin_family = AF_INET;
  local.sin_addr.s_addr = INADDR_ANY;
  local.sin_port = 0;

  if (bind(fd, (struct sockaddr *)&local, sizeof(local)) < 0)
    {
      fprintf(stderr, "ethloop: bind %s failed: %d\n", g_ifname[0], errno);
      goto errout;
    }

  ethloop_socket_options(fd);

  memset(&remote, 0, sizeof(remote));
  remote.sin_family = AF_INET;
  remote.sin_addr = g_addr[1];
  remote.sin_port = htons(g_port);

  flags = fcntl(fd, F_GETFL, 0);
  if (flags < 0 || fcntl(fd, F_SETFL, flags | O_NONBLOCK) < 0)
    {
      goto errout;
    }

  if (connect(fd, (struct sockaddr *)&remote, sizeof(remote)) < 0)
    {
      if (errno != EINPROGRESS)
        {
          goto errout;
        }

      pfd.fd = fd;
      pfd.events = POLLOUT;
      pfd.revents = 0;

      if (poll(&pfd, 1, ETHLOOP_CONNECT_MS) <= 0)
        {
          errno = ETIMEDOUT;
          goto errout;
        }

      optlen = sizeof(sockerr);
      if (getsockopt(fd, SOL_SOCKET, SO_ERROR, &sockerr, &optlen) < 0)
        {
          goto errout;
        }

      if (sockerr != 0)
        {
          errno = sockerr;
          goto errout;
        }
    }

  /* Back to blocking for the transfer loops, whose timeouts are the socket
   * options set above.
   */

  if (fcntl(fd, F_SETFL, flags) < 0)
    {
      goto errout;
    }

  return fd;

errout:
  saved = errno;
  close(fd);
  errno = saved;
  return -1;
}

/****************************************************************************
 * Name: ethloop_create_listener
 ****************************************************************************/

static int ethloop_create_listener(void)
{
  struct sockaddr_in addr;
  int flags;
  int one = 1;
  int fd;

  fd = socket(AF_INET, SOCK_STREAM, 0);
  if (fd < 0)
    {
      return -1;
    }

  setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));

  memset(&addr, 0, sizeof(addr));
  addr.sin_family = AF_INET;
  addr.sin_addr = g_addr[1];
  addr.sin_port = htons(g_port);

  if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0 ||
      listen(fd, 4) < 0)
    {
      fprintf(stderr, "ethloop: listen on %s:%u failed: %d\n", g_ifname[1],
              (unsigned)g_port, errno);
      close(fd);
      return -1;
    }

  /* Non-blocking, so that the server task can notice the deadline while it
   * waits for a client that is reconnecting.
   */

  flags = fcntl(fd, F_GETFL, 0);
  if (flags < 0 || fcntl(fd, F_SETFL, flags | O_NONBLOCK) < 0)
    {
      close(fd);
      return -1;
    }

  return fd;
}

/****************************************************************************
 * Name: ethloop_socket_show
 ****************************************************************************/

static void ethloop_socket_show(int fd)
{
  int value = 0;
  socklen_t len = sizeof(value);

  if (!g_sndbuf_shown && getsockopt(fd, SOL_SOCKET, SO_SNDBUF, &value,
                                    &len) == 0)
    {
      g_sndbuf_shown = true;
      printf("ethloop: send buffer %d B, chunk %u B, verify %s\n", value,
             (unsigned)g_chunk, g_verify ? "on" : "off");
    }
}

/****************************************************************************
 * Name: ethloop_server
 *
 * Description:
 *   One connection at a time on the if1 side.  The listener is already open
 *   when this task starts.
 *
 ****************************************************************************/

static void *ethloop_server(void *arg)
{
  int listener = (int)(intptr_t)arg;

  while (!ethloop_stopping())
    {
      struct ethloop_conn_s *conn = &g_server_conn;
      struct ethloop_io_s *primary;
      struct ethloop_io_s *secondary = NULL;
      int64_t opened;
      pthread_t tid;
      bool have_secondary = false;
      int flags;
      int fd;

      fd = accept(listener, NULL, NULL);
      if (fd < 0)
        {
          if (errno == EAGAIN || errno == EWOULDBLOCK || errno == EINTR)
            {
              usleep(100000);
              continue;
            }

          fprintf(stderr, "ethloop: accept failed: %d\n", errno);
          usleep(100000);
          continue;
        }

      /* The accepted socket must be blocking and have the same timeouts as
       * the client end.
       */

      flags = fcntl(fd, F_GETFL, 0);
      if (flags >= 0)
        {
          fcntl(fd, F_SETFL, flags & ~O_NONBLOCK);
        }

      ethloop_socket_options(fd);

      memset(conn, 0, sizeof(*conn));
      conn->fd = fd;
      conn->where = "socket";
      opened = ethloop_now_ns();

      /* The server's primary loop runs the direction the client is not
       * running as its primary: receive in tx/both, send in rx.
       */

      primary = g_mode == ETHLOOP_MODE_RX ? &g_server_rev : &g_server_fwd;

      if (g_mode == ETHLOOP_MODE_BOTH)
        {
          secondary = &g_server_rev;

          if (pthread_create(&tid, NULL, ethloop_sender, secondary) == 0)
            {
              have_secondary = true;
            }
          else
            {
              fprintf(stderr, "ethloop: server sender thread failed\n");
              conn->failed = true;
              conn->err = EAGAIN;
              conn->where = "pthread";
            }
        }

      if (!conn->failed)
        {
          if (g_mode == ETHLOOP_MODE_RX)
            {
              ethloop_sender(primary);
            }
          else
            {
              ethloop_receiver(primary);
            }
        }

      conn->stop = true;

      if (have_secondary)
        {
          shutdown(fd, SHUT_RDWR);
          pthread_join(tid, NULL);
        }

      ethloop_conn_report("server", conn,
                          ethloop_span_ms(opened, ethloop_now_ns()));
      close(fd);
    }

  return NULL;
}

/****************************************************************************
 * Name: ethloop_run_client
 *
 * Description:
 *   One established connection on the if0 side.  The main task runs the
 *   primary direction and owns the reporter; 'both' mode adds the opposite
 *   direction in a thread.
 *
 ****************************************************************************/

static void ethloop_run_client(int fd)
{
  struct ethloop_conn_s *conn = &g_client_conn;
  struct ethloop_io_s *primary;
  struct ethloop_io_s *secondary = NULL;
  int64_t opened;
  pthread_t tid;
  bool have_secondary = false;

  memset(conn, 0, sizeof(*conn));
  conn->fd = fd;
  conn->where = "socket";

  /* The client's primary is whichever direction it is the sender of, except
   * in rx mode where it is the receiver.  It is always the reporter.
   */

  primary = g_mode == ETHLOOP_MODE_RX ? &g_client_rev : &g_client_fwd;
  primary->reporter = true;

  if (g_mode == ETHLOOP_MODE_BOTH)
    {
      secondary = &g_client_rev;

      if (pthread_create(&tid, NULL, ethloop_receiver, secondary) == 0)
        {
          have_secondary = true;
        }
      else
        {
          fprintf(stderr, "ethloop: client receiver thread failed\n");
          conn->failed = true;
          conn->err = EAGAIN;
          conn->where = "pthread";
        }
    }

  ethloop_progress();
  opened = ethloop_now_ns();

  if (!conn->failed)
    {
      if (g_mode == ETHLOOP_MODE_RX)
        {
          ethloop_receiver(primary);
        }
      else
        {
          ethloop_sender(primary);
        }
    }

  conn->stop = true;

  if (have_secondary)
    {
      shutdown(fd, SHUT_RDWR);
      pthread_join(tid, NULL);
    }

  ethloop_conn_report("client", conn,
                      ethloop_span_ms(opened, ethloop_now_ns()));
  primary->reporter = false;
  close(fd);
}

/****************************************************************************
 * Name: ethloop_wait_link
 *
 * Description:
 *   Wait for the carrier on one port.  The driver polls its PHY at 1 Hz, so
 *   the link flag can lag the training by up to a second.
 *
 ****************************************************************************/

static int ethloop_wait_link(const char *ifname, int64_t deadline)
{
  uint8_t flags;

  while (ethloop_now_ns() < deadline)
    {
      flags = 0;
      if (netlib_getifstatus(ifname, &flags) == 0 &&
          (flags & IFF_RUNNING) != 0)
        {
          return 0;
        }

      usleep(100000);
    }

  return -1;
}

/****************************************************************************
 * Name: ethloop_setup_ports
 ****************************************************************************/

static int ethloop_setup_ports(void)
{
  int i;

  for (i = 0; i < 2; i++)
    {
      if (netlib_set_ipv4addr(g_ifname[i], &g_addr[i]) < 0)
        {
          fprintf(stderr, "ethloop: set %s address failed: %d\n",
                  g_ifname[i], errno);
          return -1;
        }

      if (netlib_set_ipv4netmask(g_ifname[i], &g_netmask) < 0)
        {
          fprintf(stderr, "ethloop: set %s netmask failed: %d\n",
                  g_ifname[i], errno);
          return -1;
        }

      if (netlib_ifup(g_ifname[i]) < 0)
        {
          fprintf(stderr, "ethloop: ifup %s failed: %d\n", g_ifname[i],
                  errno);
          return -1;
        }
    }

  return 0;
}

/****************************************************************************
 * Name: ethloop_check_subnet
 *
 * Description:
 *   The setup above makes both ports share a subnet; -n leaves the
 *   configuration to the user, and this is where an incompatible one is
 *   rejected with the reason.  A connection across two subnets would time
 *   out after transmitting into the wrong port and being dropped, which is
 *   indistinguishable from a dead driver.
 *
 ****************************************************************************/

static int ethloop_check_subnet(void)
{
  char name0[16];
  char name1[16];
  struct in_addr ip[2];
  struct in_addr mask[2];
  int i;

  for (i = 0; i < 2; i++)
    {
      if (netlib_get_ipv4addr(g_ifname[i], &ip[i]) < 0)
        {
          fprintf(stderr, "ethloop: %s has no IPv4 address\n", g_ifname[i]);
          return -1;
        }

      if (netlib_get_ipv4netmask(g_ifname[i], &mask[i]) < 0)
        {
          fprintf(stderr, "ethloop: cannot read %s netmask: %d\n",
                  g_ifname[i], errno);
          return -1;
        }
    }

  if (ip[0].s_addr == 0 || ip[1].s_addr == 0)
    {
      fprintf(stderr, "ethloop: both ports need an IPv4 address\n");
      return -1;
    }

  if (mask[0].s_addr != mask[1].s_addr ||
      (ip[0].s_addr & mask[0].s_addr) != (ip[1].s_addr & mask[1].s_addr))
    {
      inet_ntop(AF_INET, &ip[0], name0, sizeof(name0));
      inet_ntop(AF_INET, &ip[1], name1, sizeof(name1));

      fprintf(stderr,
              "ethloop: %s (%s) and %s (%s) are not in one subnet.\n"
              "  On a single board the two ends of the cable must share a\n"
              "  subnet: a segment for the far port's address is only sent\n"
              "  out through this port when that address is on-link here.\n"
              "  Run ethloop without -n to let it assign %s/24 and %s/24.\n",
              g_ifname[0], name0, g_ifname[1], name1, ETHLOOP_DEFAULT_ADDR0,
              ETHLOOP_DEFAULT_ADDR1);
      return -1;
    }

  return 0;
}

/****************************************************************************
 * Name: ethloop_print_ports
 ****************************************************************************/

static void ethloop_print_ports(void)
{
  char ipstr[16];
  char maskstr[16];
  struct in_addr ip;
  struct in_addr mask;
  uint8_t flags;
  int i;

  for (i = 0; i < 2; i++)
    {
      ip.s_addr = 0;
      mask.s_addr = 0;
      flags = 0;

      if (netlib_get_ipv4addr(g_ifname[i], &ip) < 0 ||
          netlib_get_ipv4netmask(g_ifname[i], &mask) < 0 ||
          netlib_getifstatus(g_ifname[i], &flags) < 0)
        {
          printf("  %-5s (not readable)\n", g_ifname[i]);
          continue;
        }

      inet_ntop(AF_INET, &ip, ipstr, sizeof(ipstr));
      inet_ntop(AF_INET, &mask, maskstr, sizeof(maskstr));
      printf("  %-5s %-15s mask %-15s %s\n", g_ifname[i], ipstr, maskstr,
             (flags & IFF_RUNNING) != 0 ? "link up" : "no carrier");
    }
}

/****************************************************************************
 * Name: ethloop_summary
 ****************************************************************************/

static void ethloop_summary(int64_t end_ns)
{
  uint64_t total_ns = (uint64_t)(end_ns - g_start_ns);
  int dir;

  printf("\nethloop summary\n");
  printf("  run      %llu.%llus, %d connection(s), %d dropped, "
         "%d connect failures\n",
         (unsigned long long)(total_ns / ETHLOOP_NS_PER_S),
         (unsigned long long)(total_ns % ETHLOOP_NS_PER_S / 100000000),
         g_connections, g_drops, g_connect_errors);

  for (dir = 0; dir < ETHLOOP_NDIR; dir++)
    {
      struct ethloop_dir_s *d = &g_dir[dir];
      char avg[24];
      char lo[24];
      char hi[24];
      uint64_t avg_x10;

      if (!ethloop_dir_active(dir))
        {
          continue;
        }

      avg_x10 = ethloop_mbit_x10(d->rx_bytes, total_ns);
      ethloop_format_x10(avg, sizeof(avg), avg_x10);

      printf("  %-9s sent %llu B, received %llu B (%llu.%llu MB)\n",
             ethloop_dir_name(dir), (unsigned long long)d->tx_bytes,
             (unsigned long long)d->rx_bytes,
             (unsigned long long)(d->rx_bytes / 1000000),
             (unsigned long long)(d->rx_bytes % 1000000 / 100000));
      printf("            average %s Mbit/s over the whole run\n", avg);

      if (d->tx_bytes > d->rx_bytes)
        {
          printf("            %llu B were still in flight when the "
                 "connection was closed\n",
                 (unsigned long long)(d->tx_bytes - d->rx_bytes));
        }

      if (d->samples > 0)
        {
          ethloop_format_x10(lo, sizeof(lo), d->min_mbit_x10);
          ethloop_format_x10(hi, sizeof(hi), d->max_mbit_x10);
          printf("            1 s samples %s .. %s Mbit/s over %llu\n", lo,
                 hi, (unsigned long long)d->samples);
        }

      if (g_verify)
        {
          printf("            verified, %llu mismatching word(s)\n",
                 (unsigned long long)d->bad_words);
        }
    }

  if (g_connections == 0)
    {
      printf("  no connection was ever established -- check the cable and "
             "that both ports are in one subnet\n");
    }
}

/****************************************************************************
 * Name: ethloop_usage
 ****************************************************************************/

static void ethloop_usage(void)
{
  printf(
      "Usage: ethloop [options]\n"
      "  -t <seconds>  test duration, 0 = until interrupted (default %d)\n"
      "  -m <mode>     tx (if0 to if1), rx (if1 to if0), both (default tx)\n"
      "  -i <ifname>   first port (default %s)\n"
      "  -j <ifname>   second port (default %s)\n"
      "  -a <addr>     address of the first port (default %s)\n"
      "  -b <addr>     address of the second port (default %s)\n"
      "  -p <port>     TCP port (default %d)\n"
      "  -s <bytes>    bytes per send/recv, <= %d (default %d)\n"
      "  -w <bytes>    send buffer size, 0 = system default (default %d)\n"
      "  -n            do not configure the interfaces\n"
      "  -c            do not check the data pattern\n"
      "  -h            this help\n"
      "\n"
      "Both ports must share one IPv4 subnet; see the comment at the top of\n"
      "app/ethloop/ethloop_main.c for why.\n",
      ETHLOOP_DEFAULT_SECONDS, ETHLOOP_DEFAULT_IF0, ETHLOOP_DEFAULT_IF1,
      ETHLOOP_DEFAULT_ADDR0, ETHLOOP_DEFAULT_ADDR1, ETHLOOP_DEFAULT_PORT,
      ETHLOOP_CHUNK_MAX, ETHLOOP_DEFAULT_CHUNK, ETHLOOP_DEFAULT_SNDBUF);
}

/****************************************************************************
 * Name: ethloop_parse_args
 ****************************************************************************/

static int ethloop_parse_args(int argc, char *argv[])
{
  int i;

  for (i = 1; i < argc; i++)
    {
      const char *opt = argv[i];
      char *end;
      const char *val;

      if (opt[0] != '-' || opt[1] == '\0')
        {
          fprintf(stderr, "ethloop: unexpected argument '%s'\n", opt);
          return -1;
        }

      if (strcmp(opt, "-h") == 0)
        {
          ethloop_usage();
          return 1;
        }

      if (strcmp(opt, "-n") == 0)
        {
          g_setup = false;
          continue;
        }

      if (strcmp(opt, "-c") == 0)
        {
          g_verify = false;
          continue;
        }

      if (i + 1 >= argc)
        {
          fprintf(stderr, "ethloop: %s needs a value\n", opt);
          return -1;
        }

      val = argv[++i];

      if (strcmp(opt, "-t") == 0)
        {
          long seconds = strtol(val, &end, 10);

          if (*end != '\0' || seconds < 0)
            {
              fprintf(stderr, "ethloop: bad -t '%s'\n", val);
              return -1;
            }

          g_seconds = (int)seconds;
        }
      else if (strcmp(opt, "-p") == 0)
        {
          long port = strtol(val, &end, 10);

          if (*end != '\0' || port < 1 || port > 65535)
            {
              fprintf(stderr, "ethloop: bad -p '%s'\n", val);
              return -1;
            }

          g_port = (uint16_t)port;
        }
      else if (strcmp(opt, "-s") == 0)
        {
          long chunk = strtol(val, &end, 10);

          if (*end != '\0' || chunk < 64 || chunk > ETHLOOP_CHUNK_MAX)
            {
              fprintf(stderr, "ethloop: -s must be 64..%d\n",
                      ETHLOOP_CHUNK_MAX);
              return -1;
            }

          g_chunk = (size_t)chunk;
        }
      else if (strcmp(opt, "-w") == 0)
        {
          long sndbuf = strtol(val, &end, 10);

          if (*end != '\0' || sndbuf < 0 || sndbuf > 1024 * 1024)
            {
              fprintf(stderr, "ethloop: bad -w '%s'\n", val);
              return -1;
            }

          g_sndbuf = (int)sndbuf;
        }
      else if (strcmp(opt, "-i") == 0)
        {
          g_ifname[0] = val;
        }
      else if (strcmp(opt, "-j") == 0)
        {
          g_ifname[1] = val;
        }
      else if (strcmp(opt, "-a") == 0 || strcmp(opt, "-b") == 0)
        {
          struct in_addr addr;

          if (inet_pton(AF_INET, val, &addr) != 1)
            {
              fprintf(stderr, "ethloop: bad address '%s'\n", val);
              return -1;
            }

          g_addr[opt[1] == 'a' ? 0 : 1] = addr;
        }
      else if (strcmp(opt, "-m") == 0)
        {
          if (strcmp(val, "tx") == 0)
            {
              g_mode = ETHLOOP_MODE_TX;
            }
          else if (strcmp(val, "rx") == 0)
            {
              g_mode = ETHLOOP_MODE_RX;
            }
          else if (strcmp(val, "both") == 0)
            {
              g_mode = ETHLOOP_MODE_BOTH;
            }
          else
            {
              fprintf(stderr, "ethloop: -m must be tx, rx or both\n");
              return -1;
            }
        }
      else
        {
          fprintf(stderr, "ethloop: unknown option '%s'\n", opt);
          return -1;
        }
    }

  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: main
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  struct sigaction act;
  int64_t link_deadline;
  pthread_t server;
  int listener;
  int ret;
  int exitcode = 0;

  g_ifname[0] = ETHLOOP_DEFAULT_IF0;
  g_ifname[1] = ETHLOOP_DEFAULT_IF1;
  inet_pton(AF_INET, ETHLOOP_DEFAULT_ADDR0, &g_addr[0]);
  inet_pton(AF_INET, ETHLOOP_DEFAULT_ADDR1, &g_addr[1]);
  inet_pton(AF_INET, ETHLOOP_DEFAULT_MASK, &g_netmask);
  g_port = ETHLOOP_DEFAULT_PORT;
  g_seconds = ETHLOOP_DEFAULT_SECONDS;
  g_mode = ETHLOOP_MODE_TX;
  g_chunk = ETHLOOP_DEFAULT_CHUNK;
  g_sndbuf = ETHLOOP_DEFAULT_SNDBUF;
  g_setup = true;
  g_verify = true;

  ret = ethloop_parse_args(argc, argv);
