/****************************************************************************
 * Name: ethloop_create_listener
 ****************************************************************************/

static int ethloop_create_listener(void)
{
  struct sockaddr_in addr;
  int flags;
  int one = 1;
  int fd;

  fd = socket(AF_INET, SOCK_STREAM, 0);
  if (fd < 0)
    {
      return -1;
    }

  setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));

  memset(&addr, 0, sizeof(addr));
  addr.sin_family = AF_INET;
  addr.sin_addr = g_addr[1];
  addr.sin_port = htons(g_port);

  if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0 ||
      listen(fd, 4) < 0)
    {
      fprintf(stderr, "ethloop: listen on %s:%u failed: %d\n", g_ifname[1],
              (unsigned)g_port, errno);
      close(fd);
      return -1;
    }

  /* Non-blocking, so that the server task can notice the deadline while it
   * waits for a client that is reconnecting.
   */

  flags = fcntl(fd, F_GETFL, 0);
  if (flags < 0 || fcntl(fd, F_SETFL, flags | O_NONBLOCK) < 0)
    {
      close(fd);
      return -1;
    }

  return fd;
}

