#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <assert.h>

static inline uint8_t pat_byte(uint64_t off)
{
  uint32_t word = (uint32_t)(off >> 2);
  return (uint8_t)(word >> (8 * (off & 3)));
}

static void pat_fill(uint8_t *buf, uint64_t off, size_t len)
{
  size_t i = 0;
  while (i < len && (off & 3) != 0) buf[i++] = pat_byte(off++);
  while (i + 4 <= len) { uint32_t w = (uint32_t)(off >> 2); memcpy(&buf[i], &w, 4); i += 4; off += 4; }
  while (i < len) buf[i++] = pat_byte(off++);
}

static uint64_t pat_check(const uint8_t *buf, uint64_t off, size_t len, uint64_t *first)
{
  size_t i = 0; uint64_t bad = 0; *first = UINT64_MAX;
  while (i < len) {
    if ((off & 3) == 0 && len - i >= 4) {
      uint32_t w; memcpy(&w, &buf[i], 4);
      if (w != (uint32_t)(off >> 2)) { if (*first == UINT64_MAX) *first = off; bad++; }
      i += 4; off += 4;
    } else {
      if (buf[i] != pat_byte(off)) { if (*first == UINT64_MAX) *first = off; bad++; }
      i++; off++;
    }
  }
  return bad;
}

int main(void)
{
  static uint8_t a[70000], b[70000];
  uint64_t first;
  for (size_t len = 1; len <= 4096; len += 37) {
    for (uint64_t off = 0; off < 17; off++) {
      memset(a, 0, sizeof(a));
      pat_fill(a, off, len);
      /* a stream split at arbitrary points must verify */
      size_t pos = 0;
      uint64_t o = off;
      int ok = 1;
      while (pos < len) {
        size_t chunk = len - pos; if (chunk > 23) chunk = 1 + (pos * 7) % 23;
        if (pat_check(a + pos, o, chunk, &first) != 0) ok = 0;
        pos += chunk; o += chunk;
      }
      assert(ok);
      /* one corrupted byte must be reported at the right offset */
      memcpy(b, a, len);
      size_t at = (len / 2);
      b[at] ^= 0x5a;
      uint64_t bad = pat_check(b, off, len, &first);
      assert(bad != 0);
      uint64_t expect = off + at;
      if ((expect & 3) == 0) { assert(first == off + (at & ~3ull)); }
      else { assert(first == expect); }
    }
  }
  puts("pattern tests pass");
  return 0;
}
