/****************************************************************************
 * Name: ethloop_drain
 *
 * Description:
 *   The one-way modes have no receiver thread, so the owner reads the socket
 *   empty after its sender's FIN.  That consumes the peer's data and its FIN
 *   and keeps the close orderly; without it the last frames would still be
 *   unacknowledged when close() ran, and close() would reset the connection.
 *
 ****************************************************************************/

static void ethloop_drain(int fd)
{
  uint8_t buf[512];
  int64_t end = ethloop_now_ns() + ETHLOOP_DRAIN_MS * ETHLOOP_NS_PER_MS;

  while (ethloop_now_ns() < end)
    {
      ssize_t n = recv(fd, buf, sizeof(buf), 0);

      if (n == 0)
        {
          break;
        }

      if (n < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          if (errno == EAGAIN || errno == EWOULDBLOCK)
            {
              continue;
            }

          break;
        }
    }
}

/****************************************************************************
 * Name: ethloop_finish
 *
 * Description:
 *   Wind a connection up once its primary loop returned.  A receiver thread
 *   (both mode) drains to the peer's FIN by itself; otherwise the owner does
 *   the drain when this side was the sender.  Only then is the socket closed.
 *
 ****************************************************************************/

static void ethloop_finish(int fd, bool primary_sends, pthread_t tid,
                           bool have_secondary)
{
  if (have_secondary)
    {
      pthread_join(tid, NULL);
    }
  else if (primary_sends)
    {
      ethloop_drain(fd);
    }

  close(fd);
}

