       * non-blocking listener returns EAGAIN for the ordinary case of no
       * client yet, and NuttX logs that as an ERROR on every poll.
       */

      pfd.fd = listener;
      pfd.events = POLLIN;
      pfd.revents = 0;

      ret = poll(&pfd, 1, 100);
      if (ret <= 0)
