static int gm_interrupt(int irq, FAR void *context, FAR void *arg)
{
  FAR struct rk3576_gmac_s *priv = arg;
  uint32_t status;
  bool txdone = false;
  bool rxready = false;
  bool macseen = false;
  irqstate_t flags;

  UNUSED(irq);
  UNUSED(context);

  flags = spin_lock_irqsave(&priv->lock);

  /* Storm breaker.  The DMA channel can re-assert its line far faster than
   * frames can be carried (450k/s was measured against a normal 49k/s), and
   * at that rate no task -- not the work queue that would make the ring
   * usable again, not the application's own recovery -- gets the CPU.  Mask
   * the channel for 10 ms on a burst and let the timer interrupt re-enable
   * it.  The normal rate is ~50 per millisecond; 200 is four times that.
   */

  if (clock_systime_ticks() != priv->irq_window)
    {
      priv->irq_window = clock_systime_ticks();
      priv->irq_streak = 0;
    }

  if (++priv->irq_streak > 200)
    {
      gm_putreg(priv, RK3576_GMAC_DMA_CH0_INTERRUPT_ENABLE, 0);
      wd_start(&priv->irqwdog, MSEC2TICK(10), gm_irq_reenable, (wdparm_t)priv);
      priv->irq_streak = 0;

      if (!priv->irqstorm_logged)
        {
          FAR struct rk3576_gmac_desc_s *d =
              gm_desc(priv->txring, priv->txdone);

          priv->irqstorm_logged = true;
          gm_desc_inval(d);

          /* The state that decides whether this is a real completion or a
           * self-triggering level: what the enable register actually holds,
           * whether the ring has any owned descriptor left, and what the
           * descriptor at the tail looks like.
           */

          syslog(LOG_ERR,
                 "gmac%d: IRQ storm, mask 10 ms: enable %08" PRIx32
                 " txnow %" PRIu32 " txdone %" PRIu32 " status %08" PRIx32
                 " des3 %08" PRIx32 " des2 %08" PRIx32 "\n",
                 priv->intf,
                 gm_getreg(priv, RK3576_GMAC_DMA_CH0_INTERRUPT_ENABLE),
                 priv->txnow, priv->txdone,
                 gm_getreg(priv, RK3576_GMAC_DMA_CH0_STATUS), d->des3,
                 d->des2);
        }
    }

  status = gm_getreg(priv, RK3576_GMAC_DMA_CH0_STATUS);

  g_gmac_irqs++;
  if (status != 0)
    {
      g_gmac_last_status = status;
    }

  gm_putreg(priv, RK3576_GMAC_DMA_CH0_STATUS, status & GM_IRQ_STATUS);

  /* A MAC-level bit can assert the shared line on its own, in which case the
   * DMA status above is zero and nothing would ever clear it.  Read and
   * clear it, and record the first non-zero value.
   */

  {
    uint32_t macstatus = gm_getreg(priv, RK3576_GMAC_MAC_INTERRUPT_STATUS);

    if (macstatus != 0)
      {
        gm_putreg(priv, RK3576_GMAC_MAC_INTERRUPT_STATUS, macstatus);
        priv->macirqs++;
        macseen = true;

        if (!priv->macirq_logged)
          {
            priv->macirq_logged = true;
            syslog(LOG_ERR, "gmac%d: MAC interrupt status 0x%08" PRIx32 "\n",
                   priv->intf, macstatus);
          }
      }
  }

  if ((status & (RK3576_GMAC_CH0STS_FBE | RK3576_GMAC_CH0STS_CDE |
                 RK3576_GMAC_CH0STS_RPS)) != 0)
    {
      syslog(LOG_ERR, "gmac%d: DMA fault, status 0x%08" PRIx32 "\n",
             priv->intf, status);
      NETDEV_RXERRORS(&priv->dev.netdev);
    }

  if ((status & RK3576_GMAC_CH0STS_TI) != 0)
    {
      priv->txirqs++;
      gm_tx_reap(priv);
      txdone = true;
    }

  if ((status & (RK3576_GMAC_CH0STS_RI | RK3576_GMAC_CH0STS_RBU)) != 0)
    {
      rxready = true;
    }

  spin_unlock_irqrestore(&priv->lock, flags);

  /* Both of these only queue work (or post a semaphore), which is what makes
   * them safe from an interrupt.  The carrier notifier is not: it takes the
   * network lock, so it runs from gm_link_work instead.
   */

  if (status == 0 && !macseen)
    {
      g_gmac_spurious++;
    }

  if (txdone)
    {
      netdev_lower_txdone(&priv->dev);
    }

  if (rxready)
    {
      netdev_lower_rxready(&priv->dev);
    }

  return OK;
}

