static void gm_reclaim(FAR struct netdev_lowerhalf_s *dev)
{
  FAR struct rk3576_gmac_s *priv = (FAR struct rk3576_gmac_s *)dev;
  irqstate_t flags;
  uint32_t before;
  uint32_t i;

  flags = spin_lock_irqsave(&priv->lock);
  before = priv->txdone;
  gm_tx_reap(priv);

  /* TEMPORARY: the stack asks for TX room, the ring is not empty, and the
   * reclaim freed nothing.  One dump of the ring in that state, because it is
   * the wedge: the DMA has either not completed the descriptors or the CPU is
   * not seeing the completion.
   */

  if (priv->txdone == before && !priv->txstall_logged &&
      netdev_lower_quota_load(&priv->dev, NETPKT_TX) <= 0)
    {
      /* A first refusal is normal while the previous burst is still in the
       * DMA; only a run of them with nothing reclaimed is the wedge.
       */

      if (++priv->txstall_count < 100)
        {
          spin_unlock_irqrestore(&priv->lock, flags);
          return;
        }

      priv->txstall_logged = true;
      syslog(LOG_ERR,
             "gmac%" PRIu8 ": TX stall txnow %" PRIu32 " txdone %" PRIu32
             " txirqs %" PRIu32 " status 0x%08" PRIx32 "\n",
             priv->intf, priv->txnow, priv->txdone, priv->txirqs,
             gm_getreg(priv, RK3576_GMAC_DMA_CH0_STATUS));

      for (i = 0; i < GM_TX_DESC; i++)
        {
          gm_desc_inval(gm_desc(priv->txring, i));
          syslog(LOG_ERR,
                 "gmac%" PRIu8 ":   txdesc[%" PRIu32 "] des3 0x%08" PRIx32
                 " pkt %p\n",
                 priv->intf, i, gm_desc(priv->txring, i)->des3,
                 priv->txpkt[i]);
        }

      spin_unlock_irqrestore(&priv->lock, flags);
      return;
    }

  if (priv->txdone != before)
    {
      priv->txstall_count = 0;
    }

  spin_unlock_irqrestore(&priv->lock, flags);
}

static void gm_tx_reap(FAR struct rk3576_gmac_s *priv)
{
  FAR struct rk3576_gmac_desc_s *desc;

  while (priv->txnow != priv->txdone)
    {
      desc = gm_desc(priv->txring, priv->txdone);
      gm_desc_inval(desc);

      if ((desc->des3 & RK3576_GMAC_TDES3_OWN) != 0)
        {
          break;
        }

      netpkt_free(&priv->dev, priv->txpkt[priv->txdone], NETPKT_TX);
      priv->txpkt[priv->txdone] = NULL;
      priv->txdone = (priv->txdone + 1) % GM_TX_DESC;
    }
}

/****************************************************************************
 * Name: gm_tx_kick
 *
 * Description:
 *   The DMA stopped while a descriptor it owns is still published: TBU set,
 *   txdone behind txnow, no progress.  From outside, "suspended at the tail"
 *   and "stopped outright" look the same.  Rewrite the tail pointer (the
 *   TRM's resume) and re-trigger StartTransmit (only effective after a stop,
 *   so the clear and the set are both needed).  Driver lock held.
 *
 ****************************************************************************/

static void gm_tx_kick(FAR struct rk3576_gmac_s *priv, bool force)
{
  FAR struct rk3576_gmac_desc_s *desc;
  uint32_t status;
  uint32_t ctrl;

  if (priv->txdone == priv->txnow)
    {
      return;
    }

  if (!force)
    {
      status = gm_getreg(priv, RK3576_GMAC_DMA_CH0_STATUS);
      if ((status & RK3576_GMAC_CH0STS_TBU) == 0)
        {
          return;
        }
    }

  desc = gm_desc(priv->txring, (priv->txnow + GM_TX_DESC - 1) % GM_TX_DESC);
  gm_putreg(priv, RK3576_GMAC_DMA_CH0_TXDESC_TAIL_PTR,
            (uint32_t)up_addrenv_va_to_pa(desc));

  ctrl = gm_getreg(priv, RK3576_GMAC_DMA_CH0_TX_CONTROL);
  gm_putreg(priv, RK3576_GMAC_DMA_CH0_TX_CONTROL,
            ctrl & ~RK3576_GMAC_CH0TX_ST);
  gm_putreg(priv, RK3576_GMAC_DMA_CH0_TX_CONTROL, ctrl | RK3576_GMAC_CH0TX_ST);
}

/****************************************************************************
 * Name: gm_tx_watchdog
 *
 * Description:
 *   Fires 10 ms after the last transmit.  If descriptors are still pending
 *   and txdone has not moved, the DMA has stopped with work in the ring, and
 *   the tail/start sequence is the only way to make it go again.
 *
 ****************************************************************************/

static void gm_tx_watchdog(wdparm_t arg)
{
  FAR struct rk3576_gmac_s *priv = (FAR struct rk3576_gmac_s *)arg;
  irqstate_t flags;

  flags = spin_lock_irqsave(&priv->lock);

  if (priv->txdone != priv->txnow)
    {
      if (priv->txdone != priv->txwd_done)
        {
          priv->txwd_done = priv->txdone;
        }
      else
        {
          FAR struct rk3576_gmac_desc_s *d =
              gm_desc(priv->txring, priv->txdone);

          gm_desc_inval(d);
          gm_tx_kick(priv, true);

          if (!priv->txstall2_logged)
            {
              priv->txstall2_logged = true;
              syslog(LOG_ERR,
                     "gmac%d: TX stuck, kicked: txnow %" PRIu32
                     " txdone %" PRIu32 " status %08" PRIx32 " mtl %08" PRIx32
                     " op %08" PRIx32 " cur %08" PRIx32 " cfg %08" PRIx32
                     " under %08" PRIx32 " mdbg %08" PRIx32 " des3 %08" PRIx32
                     " des2 %08" PRIx32 "\n",
                     priv->intf, priv->txnow, priv->txdone,
                     gm_getreg(priv, RK3576_GMAC_DMA_CH0_STATUS),
                     gm_getreg(priv, RK3576_GMAC_MTL_TXQ0_DEBUG),
                     gm_getreg(priv, RK3576_GMAC_MTL_TXQ0_OPERATION_MODE),
                     gm_getreg(priv, RK3576_GMAC_DMA_CH0_CURRENT_APP_TXDESC),
                     gm_getreg(priv, RK3576_GMAC_MAC_CONFIGURATION),
                     gm_getreg(priv, RK3576_GMAC_MTL_TXQ0_UNDERFLOW),
                     gm_getreg(priv, RK3576_GMAC_MAC_DEBUG), d->des3, d->des2);
            }
        }

      wd_start(&priv->txwdog, MSEC2TICK(10), gm_tx_watchdog, (wdparm_t)priv);
    }

  spin_unlock_irqrestore(&priv->lock, flags);
}

