          syslog(LOG_ERR,
                 "gmac%d: IRQ storm: enable %08" PRIx32 " status %08" PRIx32
                 " macsts %08" PRIx32 " macken %08" PRIx32 " txnow %" PRIu32
                 " txdone %" PRIu32 " des3 %08" PRIx32 " des2 %08" PRIx32 "\n",
                 priv->intf, enable, status,
                 gm_getreg(priv, RK3576_GMAC_MAC_INTERRUPT_STATUS),
                 gm_getreg(priv, RK3576_GMAC_MAC_INTERRUPT_ENABLE),
                 priv->txnow, priv->txdone, d->des3, d->des2);
