{
  int announced = 0;
  int64_t last_wake = ethloop_now_ns();

  UNUSED(arg);

  while (!g_stop)
    {
      usleep(1000000);

      /* If a 1 s sleep returns much later, the CPU is not being given to
       * tasks at all -- an interrupt storm, or a spin above this priority.
